class _Official_bench_lib_Unique(_Official_common_Benchmark):
    """Benchmark for np.unique with np.nan values."""
    param_names = ['array_size', 'percent_nans', 'percent_unique_values', 'dtype']
    params = [[200, int(200000.0)], [0.0, 10.0, 90.0], [0.2, 20.0], [np.float64, np.complex128, np.dtypes.StringDType(na_object=np.nan)]]

    def setup(self, array_size, percent_nans, percent_unique_values, dtype):
        rng = np.random.default_rng(123)
        unique_values_size = max(int(percent_unique_values / 100.0 * array_size), 2)
        match dtype:
            case np.float64:
                unique_array = rng.uniform(size=unique_values_size).astype(dtype)
            case np.complex128:
                unique_array = np.array([complex(*rng.uniform(size=2)) for _ in range(unique_values_size)], dtype=dtype)
            case np.dtypes.StringDType():
                chars = string.ascii_letters + string.digits
                unique_array = np.array([''.join(rng.choice(list(chars), size=rng.integers(4, 8))) for _ in range(unique_values_size)], dtype=dtype)
            case _:
                raise ValueError(f'Unsupported dtype {dtype}')
        base_array = np.resize(unique_array, array_size)
        rng.shuffle(base_array)
        n_nan = int(percent_nans / 100.0 * array_size)
        nan_indices = rng.choice(np.arange(array_size), size=n_nan, replace=False)
        base_array[nan_indices] = np.nan
        self.arr = base_array

    def time_unique_values(self, array_size, percent_nans, percent_unique_values, dtype):
        np.unique(self.arr, return_index=False, return_inverse=False, return_counts=False)

    def time_unique_counts(self, array_size, percent_nans, percent_unique_values, dtype):
        np.unique(self.arr, return_index=False, return_inverse=False, return_counts=True)

    def time_unique_inverse(self, array_size, percent_nans, percent_unique_values, dtype):
        np.unique(self.arr, return_index=False, return_inverse=True, return_counts=False)

    def time_unique_all(self, array_size, percent_nans, percent_unique_values, dtype):
        np.unique(self.arr, return_index=True, return_inverse=True, return_counts=True)

